#!/usr/bin/env python3
from pwn import *

# Connect to the service
conn = remote('pwn.chal.csaw.io', 5000)

# Receive the initial prompts
print(conn.recvuntil(b'zopnol?').decode())

# Try a different variation
first_answer = 133337777
conn.sendline(str(first_answer).encode())

# Get the response with a longer timeout
try:
    response = conn.recv(1024, timeout=5).decode()
    print(f"Response:\n{response}")

    # Try to receive more if available
    while True:
        try:
            more = conn.recv(1024, timeout=2).decode()
            if more:
                print(more)
            else:
                break
        except:
            break

except EOFError:
